//! Immutable host configuration. No identity defaults are generated by the browser.
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use sha2::{Digest, Sha256};
use std::path::{Path, PathBuf};

pub const SOURCE_VERSION: &str = "7c751c5cd8833ac951d48320218c4fe91aa97ac8";

#[derive(Clone, Debug, Deserialize, Serialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct Resolved {
    pub user_agent: String,
    pub platform: String,
    pub locale: String,
    pub languages: Vec<String>,
    pub timezone: String,
    pub hardware_concurrency: u32,
    pub device_memory: f64,
    pub screen_width: u32,
    pub screen_height: u32,
    pub avail_width: u32,
    pub avail_height: u32,
    pub color_depth: u32,
    pub pixel_depth: u32,
    pub device_scale_factor: f64,
    pub fonts: Vec<String>,
    pub gl_backend: String,
}
#[derive(Clone, Debug, Deserialize, Serialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct Runtime {
    pub id: String, pub version: String, pub artifact_sha256: String,
    pub adapter_version: String, pub binary: PathBuf,
}
#[derive(Clone, Debug, Deserialize, Serialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct Assets { pub fonts_sha256: String, pub render_config_sha256: String }
#[derive(Clone, Debug, Deserialize, Serialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct AssetPaths { pub fonts: Vec<PathBuf> }
#[derive(Clone, Debug, Deserialize, Serialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct Network {
    pub proxy_ref: Option<String>, pub egress_policy: String,
    #[serde(default)] pub allow_private_network: bool,
}
#[derive(Clone, Debug, Deserialize, Serialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct Storage { pub format_version: u32, pub path: PathBuf }
#[derive(Clone, Debug, Deserialize, Serialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct Environment {
    pub schema: u32, pub id: String, pub revision: u64, pub seed: String,
    pub generator_version: String, pub runtime: Runtime,
    pub overrides: Value, pub resolved: Resolved, pub assets: Assets,
    pub asset_paths: AssetPaths, pub network: Network, pub storage: Storage,
    pub permissions: std::collections::BTreeMap<String, String>,
    pub capabilities: Value, pub identity_scope: String,
    #[serde(default)] pub name: String,
    #[serde(default)] pub mode: String,
    pub resolved_sha256: String,
    #[serde(default)] pub previous_environment_sha256: Option<String>,
    #[serde(default)] pub created_at: Option<String>,
    #[serde(skip)] pub environment_sha256: String,
    #[serde(skip)] source_bytes: std::sync::Arc<[u8]>,
}
fn sha(bytes: &[u8]) -> String { format!("{:x}", Sha256::digest(bytes)) }
fn canonical_sha(value: &mut Value) -> serde_json::Result<String> {
    // Explicitly canonicalize even when another dependency enables preserve_order.
    value.sort_all_objects();
    Ok(sha(&serde_json::to_vec(value)?))
}
fn fail(message: impl std::fmt::Display) -> anyhow::Error { anyhow::anyhow!("invalid_config: {message}") }
static LOADED_ENVIRONMENT: std::sync::OnceLock<Environment> = std::sync::OnceLock::new();
pub fn install_loaded(environment: Environment) -> anyhow::Result<()> {
    LOADED_ENVIRONMENT.set(environment).map_err(|_| fail("a process may load only one environment revision"))
}
impl Environment {
    pub fn read(path: &Path) -> anyhow::Result<Self> {
        let bytes = std::fs::read(path).map_err(fail)?;
        let mut env: Self = serde_json::from_slice(&bytes).map_err(fail)?;
        env.environment_sha256 = sha(&bytes);
        let mut raw: Value = serde_json::from_slice(&bytes).map_err(fail)?;
        env.source_bytes = std::sync::Arc::from(bytes.as_slice());
        if canonical_sha(&mut raw["resolved"])? != env.resolved_sha256 {
            return Err(fail("resolved input digest mismatch"));
        }
        if env.overrides.as_object().is_some_and(|overrides| overrides.iter()
            .any(|(name, value)| raw["resolved"].get(name) != Some(value))) {
            return Err(fail("unknown or unapplied override"));
        }
        let r = &env.resolved;
        if env.schema != 3 || env.id.is_empty() || env.revision == 0
            || env.generator_version.is_empty() || env.seed.is_empty()
            || !env.seed.bytes().all(|c| c.is_ascii_hexdigit())
            || env.identity_scope != "environment" || env.runtime.id != "obscura"
            || env.runtime.version != SOURCE_VERSION || env.runtime.adapter_version.is_empty()
            || env.storage.format_version != 1 || !env.storage.path.is_absolute()
            || !env.overrides.is_object() || !env.capabilities.is_object() {
            return Err(fail("schema/id/revision/runtime/storage contract mismatch"));
        }
        let safe = |s: &str| !s.is_empty() && !s.bytes().any(|b| b < 32 || b == 127);
        let locale = |s: &str| safe(s) && s.len() <= 128
            && s.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'-');
        if !safe(&r.user_agent) || r.user_agent.len() > 8192 || !safe(&r.platform) || !locale(&r.locale)
            || r.languages.is_empty() || r.languages[0] != r.locale
            || r.languages.iter().any(|s| !locale(s)) || !safe(&r.timezone)
            || r.timezone.contains("..") || r.timezone.starts_with('/')
            || r.hardware_concurrency == 0 || r.hardware_concurrency > 256
            || ![0.25,0.5,1.0,2.0,4.0,8.0].contains(&r.device_memory)
            || r.screen_width == 0 || r.screen_height == 0
            || r.screen_width > 16384 || r.screen_height > 16384
            || r.avail_width == 0 || r.avail_height == 0
            || r.avail_width > r.screen_width || r.avail_height > r.screen_height
            || r.color_depth != 24 || r.pixel_depth != 24
            || !r.device_scale_factor.is_finite() || r.device_scale_factor <= 0.0
            || ![0.5,1.0,1.25,1.5,1.75,2.0,2.5,3.0,4.0].contains(&r.device_scale_factor)
            || !matches!(r.gl_backend.as_str(), "cgl-default" | "cgl-accelerated" | "cgl-generic-float")
            || r.fonts.iter().any(|s| !safe(s)) {
            return Err(fail("invalid resolved fields; software surface supports 24-bit RGB only"));
        }
        if !Path::new("/usr/share/zoneinfo").join(&r.timezone).is_file() {
            return Err(fail("timezone asset unavailable"));
        }
        if !env.runtime.binary.is_absolute()
            || std::fs::canonicalize(&env.runtime.binary).map_err(fail)? != std::fs::canonicalize(std::env::current_exe()?).map_err(fail)?
            || sha(&std::fs::read(&env.runtime.binary).map_err(fail)?) != env.runtime.artifact_sha256 {
            return Err(fail("runtime artifact digest/path mismatch"));
        }
        if env.asset_paths.fonts.is_empty() { return Err(fail("explicit font assets are required, including CJK when used")); }
        let mut manifest = Vec::new();
        for font in &env.asset_paths.fonts {
            if !font.is_absolute() || !font.is_file() { return Err(fail("font asset unavailable")); }
            manifest.push(sha(&std::fs::read(font).map_err(fail)?));
        }
        manifest.sort(); manifest.dedup();
        if sha(&serde_json::to_vec(&manifest)?) != env.assets.fonts_sha256 {
            return Err(fail("font asset manifest digest mismatch"));
        }
        let scale = format!("{:.6}", r.device_scale_factor);
        let scale = scale.trim_end_matches('0').trim_end_matches('.');
        let mut render = json!({"device_scale_factor":scale,"color_depth":r.color_depth,
            "pixel_depth":r.pixel_depth,"screen_width":r.screen_width,"screen_height":r.screen_height,"fonts":r.fonts,"gl_backend":r.gl_backend});
        if canonical_sha(&mut render)? != env.assets.render_config_sha256 {
            return Err(fail("render configuration digest mismatch"));
        }
        if !matches!(env.network.egress_policy.as_str(), "strict" | "observe")
            || env.permissions.values().any(|v| v != "deny") {
            return Err(fail("unsupported egress policy or permission grant; this backend implements deny only"));
        }
        if let Some(reference) = &env.network.proxy_ref {
            let key = reference.strip_prefix("env:").filter(|s| !s.is_empty()).ok_or_else(|| fail("proxy_ref must use env:VAR"))?;
            let proxy = std::env::var(key).map_err(|_| fail("proxy secret reference unavailable"))?;
            let url = url::Url::parse(&proxy).map_err(fail)?;
            if !matches!(url.scheme(), "http" | "https" | "socks5h") || url.host_str().is_none() {
                return Err(fail("proxy must be http/https or remote-DNS socks5h; no direct fallback"));
            }
            if std::env::var("OBSCURA_PROXY").ok().as_deref() != Some(proxy.as_str()) {
                return Err(fail("proxy reference differs from native transport configuration"));
            }
        } else if std::env::var("OBSCURA_PROXY").is_ok_and(|s| !s.is_empty()) {
            return Err(fail("proxy transport configured without an environment proxy_ref"));
        }
        Ok(env)
    }
    fn same_semantic_inputs(&self, other: &Self) -> bool {
        self.schema == other.schema && self.id == other.id && self.revision == other.revision
            && self.seed == other.seed && self.generator_version == other.generator_version
            && self.overrides == other.overrides && self.resolved == other.resolved
            && self.assets == other.assets && self.network == other.network
            && self.permissions == other.permissions && self.identity_scope == other.identity_scope
            && self.storage.format_version == other.storage.format_version
            && self.runtime.id == other.runtime.id && self.runtime.version == other.runtime.version
            && self.runtime.artifact_sha256 == other.runtime.artifact_sha256
            && self.runtime.adapter_version == other.runtime.adapter_version
    }
    pub fn load(storage: Option<&Path>, stealth: bool, cli_ua: Option<&str>) -> Option<Self> {
        let path = std::env::var_os("OBSCURA_ENVIRONMENT")?;
        Some((|| -> anyhow::Result<Self> {
            let env = match LOADED_ENVIRONMENT.get() {
                Some(environment) => environment.clone(),
                None => Self::read(Path::new(&path))?,
            };
            if stealth || cli_ua.is_some() || storage != Some(env.storage.path.as_path()) {
                return Err(fail("conflicting CLI identity/storage configuration"));
            }
            std::fs::create_dir_all(&env.storage.path)?;
            let record = env.storage.path.join("resolved-environment.json");
            let bytes = env.source_bytes.clone();
            if record.exists() {
                let previous_bytes = std::fs::read(&record)?;
                if sha(&previous_bytes) == env.environment_sha256 { return Ok(env); }
                let old: Self = serde_json::from_slice(&previous_bytes)
                    .map_err(|error| anyhow::anyhow!("incompatible_profile: prior native record requires explicit migration: {error}"))?;
                if !env.same_semantic_inputs(&old)
                    && (old.id != env.id || old.revision >= env.revision
                        || env.previous_environment_sha256.as_deref() != Some(sha(&previous_bytes).as_str())) {
                    anyhow::bail!("incompatible_profile: persisted semantic inputs/runtime/assets differ; explicit migration required");
                }
                let history = env.storage.path.join("revisions");
                std::fs::create_dir_all(&history)?;
                let previous = history.join(format!("{}.json", sha(&previous_bytes)));
                if !previous.exists() {
                    use std::io::Write;
                    let mut file = std::fs::OpenOptions::new().write(true).create_new(true).open(previous)?;
                    file.write_all(&previous_bytes)?; file.sync_all()?;
                    std::fs::File::open(&history)?.sync_all()?;
                }
            }
            use std::io::Write;
            let tmp = record.with_extension("json.tmp");
            let mut file = std::fs::OpenOptions::new().write(true).create(true).truncate(true).open(&tmp)?;
            file.write_all(&bytes)?; file.sync_all()?;
            std::fs::rename(&tmp, &record)?;
            std::fs::File::open(&env.storage.path)?.sync_all()?;
            Ok(env)
        })().unwrap_or_else(|error| panic!("{error}")))
    }
    pub fn receipt(&self) -> Value {
        json!({"schema":3,"id":self.id,"revision":self.revision,"environment_sha256":self.environment_sha256,
            "runtime":{"id":"obscura","version":SOURCE_VERSION},"assets":self.assets,
            "capabilities":native_capabilities()})
    }
}
static BACKEND_CAPABILITIES: std::sync::OnceLock<Value> = std::sync::OnceLock::new();
pub fn initialize_backends(environment: &Environment) -> anyhow::Result<()> {
    #[cfg(feature = "render")]
    let graphics = obscura_js::graphics::preflight().map_err(|error| anyhow::anyhow!("capability_unavailable: {error}"))?;
    #[cfg(not(feature = "render"))]
    anyhow::bail!("capability_unavailable: managed environments require --features render");
    #[cfg(feature = "render")]
    {
        if sha(&serde_json::to_vec(&graphics["fonts_sha256"])?) != environment.assets.fonts_sha256 {
            anyhow::bail!("invalid_config: actual loaded font bytes differ from pinned assets");
        }
        let components: Value = serde_json::from_str(include_str!("../../obscura-js/js/media-worker-components.json"))?;
        let caps = json!({
            "page_css":{"state":"implemented","reason":"authoritative DOM taffy/cosmic-text/tiny-skia renderer"},
            "storage":{"state":"implemented","reason":"Cookie/LocalStorage/IndexedDB write-through durable commits"},
            "http_proxy":{"state":"implemented","reason":"shared navigation/resource/Worker HTTP transport; no direct fallback"},
            "webrtc_transport":{"state":"unsupported","reason":"no native WebRTC transport or packet-leak coverage"},
            "websocket_transport":{"state":"unsupported","reason":"no native WebSocket transport"},
            "udp_transport":{"state":"unsupported","reason":"no native UDP transport"},
            "canvas":{"state":"implemented","reason":"native font shaping, rasterization and geometry","details":graphics["canvas"]},
            "webgl":{"state":"implemented","reason":"actual CGL/OpenGL backend; supported subset only","details":graphics["gl"]},
            "worker":{"state":"implemented","reason":"dedicated OS thread and independent V8 isolate, async structured messages",
                "unsupported":components["worker"]["unsupported"]},
            "audio":{"state":"implemented","reason":"web-audio-engine offline DSP graph; no fabricated hardware audio output",
                "backend":components["audio"]["backend"],"unsupported":components["audio"]["unsupported"]}
        });
        BACKEND_CAPABILITIES.set(caps).map_err(|_| anyhow::anyhow!("invalid_config: backend already initialized"))?;
        Ok(())
    }
}
pub fn native_capabilities() -> Value {
    BACKEND_CAPABILITIES.get().cloned().unwrap_or_else(|| json!({}))
}

#[cfg(test)]
mod tests {
    use super::{canonical_sha, sha};
    use serde_json::{json, Value};

    #[test]
    fn native_canonical_digests_ignore_object_insertion_order_and_keep_utf8() {
        let mut value: Value = serde_json::from_str(r#"{"z":{"width":1280,"height":720},"fonts":["Noto 日本語"],"a":1.25}"#).unwrap();
        let mut reordered = json!({"a":1.25,"fonts":["Noto 日本語"],"z":{"height":720,"width":1280}});
        let expected = sha(r#"{"a":1.25,"fonts":["Noto 日本語"],"z":{"height":720,"width":1280}}"#.as_bytes());
        assert_eq!(canonical_sha(&mut value).unwrap(), expected);
        assert_eq!(canonical_sha(&mut reordered).unwrap(), expected);
    }
}
